//! The `bsc bluetooth` command surface. Radio-free: it reads captured [`Observation`]s (a JSON array,
//! from `--file` or stdin) and runs the analyzer. A live BlueZ capture that PRODUCES those observations
//! is a separate, later layer — keeping capture out of here is what lets every decision be unit-tested.

use crate::{analyze, build_profiles, DeviceProfile, Observation, Thresholds};
use bsc_cli_util::CmdDoc;
use std::collections::BTreeMap;
use std::io::Read;

pub const COMMANDS: &[CmdDoc] = &[
    CmdDoc {
        name: "analyze",
        summary: "run the spoofing + malicious-signal detectors over a capture",
        usage: "USAGE:\n  bsc bluetooth analyze [--file <observations.json>] [--baseline <profiles.json>] [--json]\n\nReads BLE observations (a JSON array; stdin if no --file) and reports findings, most-severe first. With --baseline it also runs the baseline-relative spoof detectors (rssi/interval/service). Detectors: address-twin · rssi-deviation · interval-anomaly · service-mismatch · tracker-non-rotation · rogue-scan.",
    },
    CmdDoc {
        name: "profile",
        summary: "learn the baseline (normal operation) from a clean capture",
        usage: "USAGE:\n  bsc bluetooth profile [--file <observations.json>] [--json]\n\nLearns a per-device profile (RSSI distribution, cadence, services, address behaviour) — the NORMAL operation a spoof is measured against. Save it and pass it to `analyze --baseline`.",
    },
    CmdDoc {
        name: "kinds",
        summary: "list the detector kinds and what each catches",
        usage: "USAGE:\n  bsc bluetooth kinds",
    },
];

fn flag<'a>(args: &'a [String], name: &str) -> Option<&'a str> {
    args.iter().position(|a| a == name).and_then(|i| args.get(i + 1)).map(String::as_str)
}
fn has_flag(args: &[String], name: &str) -> bool {
    args.iter().any(|a| a == name)
}

/// Read the input JSON from `--file <path>`, or stdin when absent.
fn read_input(args: &[String]) -> Result<String, String> {
    match flag(args, "--file") {
        Some(p) => std::fs::read_to_string(p).map_err(|e| format!("read {p}: {e}")),
        None => {
            let mut s = String::new();
            std::io::stdin().read_to_string(&mut s).map_err(|e| format!("read stdin: {e}"))?;
            Ok(s)
        }
    }
}

fn read_observations(args: &[String]) -> Result<Vec<Observation>, String> {
    let raw = read_input(args)?;
    serde_json::from_str(&raw).map_err(|e| format!("parse observations: {e} (expected a JSON array of observations)"))
}

fn read_baseline(args: &[String]) -> Result<Option<BTreeMap<String, DeviceProfile>>, String> {
    match flag(args, "--baseline") {
        None => Ok(None),
        Some(p) => {
            let raw = std::fs::read_to_string(p).map_err(|e| format!("read {p}: {e}"))?;
            serde_json::from_str(&raw).map(Some).map_err(|e| format!("parse baseline: {e}"))
        }
    }
}

pub fn run(args: Vec<String>, prog: &str) -> Result<(), String> {
    match args.first().map(String::as_str).unwrap_or("") {
        "analyze" => cmd_analyze(&args[1..]),
        "profile" => cmd_profile(&args[1..]),
        "kinds" => {
            print_kinds();
            Ok(())
        }
        "" | "help" | "-h" | "--help" => {
            print_help(prog);
            Ok(())
        }
        other => Err(format!("{prog}: unknown command '{other}' — try `{prog} help`")),
    }
}

fn cmd_analyze(args: &[String]) -> Result<(), String> {
    let obs = read_observations(args)?;
    let base = read_baseline(args)?;
    let findings = analyze(&obs, base.as_ref(), &Thresholds::default());
    if has_flag(args, "--json") {
        println!("{}", serde_json::to_string(&findings).map_err(|e| e.to_string())?);
    } else if findings.is_empty() {
        println!("no findings — {} observation(s) look like normal operation", obs.len());
    } else {
        for f in &findings {
            println!("[{}] {}  {}  — {}", f.severity, f.kind, f.addr, f.summary);
        }
    }
    Ok(())
}

fn cmd_profile(args: &[String]) -> Result<(), String> {
    let obs = read_observations(args)?;
    let profiles = build_profiles(&obs);
    if has_flag(args, "--json") {
        println!("{}", serde_json::to_string(&profiles).map_err(|e| e.to_string())?);
    } else {
        for (addr, p) in &profiles {
            println!(
                "{addr} [{}]  n={}  rssi={:.0}±{:.1} dBm  every {:.0} ms  services={}  {}",
                p.addr_type, p.count, p.rssi_mean, p.rssi_std, p.interval_mean_ms, p.services.len(),
                if p.connectable { "connectable" } else { "non-connectable" }
            );
        }
    }
    Ok(())
}

fn print_kinds() {
    let rows = [
        ("address-twin", "high", "one address radiating from two places at once — a clone"),
        ("service-mismatch", "high", "a known address advertising a name/service/vendor it never had — imperfect clone"),
        ("rssi-deviation", "medium", "a known device at the wrong signal footprint — spoofer transmitting from elsewhere"),
        ("interval-anomaly", "medium", "a known identity at the wrong advertising cadence"),
        ("tracker-non-rotation", "medium", "a random address that never rotates — an unwanted tracker"),
        ("rogue-scan", "medium", "a source flooding scan requests — active recon"),
    ];
    println!("bsc bluetooth detectors:\n");
    for (k, sev, d) in rows {
        println!("  {k:22} [{sev:6}] {d}");
    }
    println!("\nSpoofing is caught by DEVIATION from a learned baseline (pass one to `analyze --baseline`),");
    println!("because a good spoof is signature-clean and only its physical/timing footprint gives it away.");
}

fn print_help(prog: &str) {
    println!("{prog} — DEFENSIVE Bluetooth analysis: catch spoofing + malicious signals from the air, passively\n");
    for c in COMMANDS {
        println!("  {:8} {}", c.name, c.summary);
    }
    println!("\nRadio-free: feed it captured BLE observations (JSON). Live BlueZ capture is a separate layer.");
}
